package com.example.nasconsports
import android.os.Handler
import android.os.Looper
import android.view.View
import android.widget.*
import org.json.JSONObject
import org.json.JSONArray
import java.util.UUID

fun MainActivity.leaguePicker(after:()->Unit){val leagues=(data.optJSONArray("leagues")?:JSONArray()).objects();if(leagues.isEmpty()){card("No leagues yet","Ask the organizer to prepare the competition demonstration, then refresh.");return};val p=picker("League",leagues.map{it.optString("name",it.optString("league_id"))});val initial=leagues.indexOfFirst{it.optString("league_id")==selectedLeague}.coerceAtLeast(0);selectedLeague=leagues[initial].getString("league_id");p.setSelection(initial);var first=true;p.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onNothingSelected(v:AdapterView<*>?){};override fun onItemSelected(a:AdapterView<*>?,v:View?,pos:Int,id:Long){val chosen=leagues[pos].getString("league_id");if(first){first=false;return};if(chosen!=selectedLeague){selectedLeague=chosen;after()}}}}
fun MainActivity.fixturesScreen(){start("Fixtures");text("Match centre",28f,true);leaguePicker{fixturesScreen()};button("Refresh fixtures"){refresh{fixturesScreen()}};val fixtures=(data.optJSONArray("fixtures")?:JSONArray()).objects().filter{it.optString("league_id")==selectedLeague};if(fixtures.isEmpty())card("No fixtures scheduled","Switch league or refresh your workspace.");for(f in fixtures){val h=f.optJSONObject("home");val a=f.optJSONObject("away");val home=h?.optString("team_id")?:f.optString("home");val away=a?.optString("team_id")?:f.optString("away");val score=if(h!=null)"${h.optInt("score")}  :  ${a?.optInt("score")?:0}"else"vs";card("$home   $score   $away","${f.optString("sport_id").uppercase()} • ${f.optString("status","upcoming").replace('_',' ')}\n${f.optString("scheduled_at","Time to be announced")}\nOpen score & timeline →"){matchScreen(f.getString("match_id"))}}}
fun MainActivity.standingsScreen(){start("Standings");text("The race to qualify",26f,true);leaguePicker{standingsScreen()};button("Refresh standings"){standingsScreen()};if((data.optJSONArray("leagues")?.length()?:0)==0)return;fetch("/audit/v1/standings/$selectedLeague"){r->card("Top ${r.optInt("qualification_spots")} qualify","P = played • W/D/L = won/drawn/lost\nDiff = score differential • Pts = points");val horizontal=HorizontalScrollView(this);val table=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};horizontal.addView(table);content.addView(horizontal);text("#    Team                 P    W    D    L   Diff   Pts",14f,true,table).typeface=android.graphics.Typeface.MONOSPACE;for(row in (r.optJSONArray("table")?:JSONArray()).objects()){val line="%-3s  %-18s %2d   %2d   %2d   %2d  %4s   %3d".format(row.optInt("rank"),row.optString("team_id"),row.optInt("played"),row.optInt("won"),row.optInt("drawn"),row.optInt("lost"),row.optString("diff"),row.optInt("points"));text(line,14f,true,table).typeface=android.graphics.Typeface.MONOSPACE;text("       Qualification: "+row.optString("status").replace('_',' '),13f,false,table)};text("League matches",20f,true);for(f in (data.optJSONArray("fixtures")?:JSONArray()).objects().filter{it.optString("league_id")==selectedLeague}){val h=f.optJSONObject("home")?.optString("team_id")?:f.optString("home");val a=f.optJSONObject("away")?.optString("team_id")?:f.optString("away");card("$h vs $a","Open match →"){matchScreen(f.getString("match_id"))}}}}
fun MainActivity.matchScreen(id:String){matchId=id;start("Match detail");val stamp=generation;button("Refresh score"){matchScreen(id)};fetch("/audit/v1/score/$id"){m->val home=m.getJSONObject("home");val away=m.getJSONObject("away");card("${home.getString("team_id")}  ${home.optInt("score")} : ${away.optInt("score")}  ${away.getString("team_id")}","${m.optString("sport_id").uppercase()} • ${m.optString("status").replace('_',' ')}\nOutcome: ${m.optString("outcome").replace('_',' ')} • Version ${m.optInt("version")}");if(canScore){if(m.optString("status")=="upcoming")button("Start match"){submitMutation("score_event",m.optInt("version"),JSONObject().put("event_id",UUID.randomUUID().toString()).put("match_id",id).put("type","match_start").put("payload",JSONObject())){matchScreen(id)}};if(m.optString("status")=="in_progress"){val teams=listOf(home.getString("team_id"),away.getString("team_id"));val tp=picker("Scoring team",teams);val config=data.optJSONObject("sports")?.optJSONObject(m.optString("sport_id"))?.optJSONObject("scoring_events");val events=config?.keys()?.asSequence()?.toList()?:emptyList();val ep=picker("Configured scoring event",events.map{it.replace('_',' ')});if(events.isNotEmpty())button("Append score event"){val body=JSONObject().put("event_id",UUID.randomUUID().toString()).put("match_id",id).put("type","score").put("payload",JSONObject().put("team_id",teams[tp.selectedItemPosition]).put("event_type",events[ep.selectedItemPosition]));submitMutation("score_event",m.optInt("version"),body){matchScreen(id)}}}}
text("Match timeline",21f,true);val timeline=(m.optJSONArray("events")?:JSONArray()).objects();if(timeline.isEmpty())card("Kick-off is ahead","Scoring events will appear here.");for(e in timeline){val p=e.optJSONObject("payload")?:JSONObject();val box=card("#${e.optInt("sequence")}  ${e.optString("type").replace('_',' ')}",listOf(p.optString("team_id"),p.optString("event_type").replace('_',' '),if(e.optBoolean("compensated"))"Corrected by a compensating event" else "",p.optString("reason")).filter{it.isNotBlank()}.joinToString(" • "));if(canScore&&e.optString("type") in listOf("score","discipline","tiebreak_winner")&&!e.optBoolean("compensated"))button("Correct this event",box){val reason=EditText(this).apply{hint="Reason for correction";minHeight=dp(56)};androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Append compensation").setView(reason).setNegativeButton("Cancel",null).setPositiveButton("Confirm"){_,_->if(reason.text.isBlank())notice("A correction reason is required.")else{val b=JSONObject().put("event_id",UUID.randomUUID().toString()).put("match_id",id).put("type","compensation").put("payload",JSONObject().put("compensates",e.getString("event_id")).put("reason",reason.text.toString()));submitMutation("score_event",m.optInt("version"),b){matchScreen(id)}}}.show()}}
button("View league standings"){selectedLeague=m.optString("league_id",selectedLeague);standingsScreen()}
if(m.optString("status")=="in_progress"&&online)Handler(Looper.getMainLooper()).postDelayed({if(!isDestroyed&&generation==stamp&&screen=="Match detail"&&hasWindowFocus()&&!busy){pollMatch(id,m.optInt("version"),stamp)}},12000)
}}
fun MainActivity.pollMatch(id:String,version:Int,stamp:Int){if(generation!=stamp)return;work({val r=api.call("/audit/v1/score/$id");local.put("$owner:/audit/v1/score/$id",r);r},{r->if(r.optInt("version")!=version)matchScreen(id)else Handler(Looper.getMainLooper()).postDelayed({if(!isDestroyed&&generation==stamp&&hasWindowFocus()&&!busy)pollMatch(id,version,stamp)},12000)},{banner()})}
fun MainActivity.submitMutation(type:String,base:Int,payload:JSONObject,done:()->Unit){val path=if(type=="score_event")"/api/v1/events"else"/api/v1/roster/transfer";if(forcedOffline()||!online){online=false;local.queue(owner,type,base,payload);banner();notice("Saved on this device. Review and sync from Offline changes.");done();return};work({api.call(path,payload)},{r->notice("Accepted • "+r.optString("state",if(type=="score_event")"Score event recorded"else"Roster updated"));done()},{e->if(e is ApiError)notice((e.message?:"Action rejected")+"\n"+e.code.replace('_',' ').lowercase())else{local.queue(owner,type,base,payload);banner();notice("Connection lost. Action saved with a stable ID for safe sync.");done()}})}
fun MainActivity.queueScreen(){start("Sync queue");text("Your offline changes",26f,true);text("Changes belong to ${user.optString("email")}. Sign in to the same account and server to sync.",14f);val actions=local.actions(owner);val pending=local.actions(owner,true);button("Sync ${pending.length()} pending changes"){if(pending.length()==0)notice("There are no pending changes.")else{banner("Syncing…");val device=prefs.getString("device",null)?:UUID.randomUUID().toString().also{prefs.edit().putString("device",it).commit()};work({api.call("/api/v1/offline-sync",JSONObject().put("device_id",device).put("actions",pending)).also{r->for(result in (r.optJSONArray("results")?:JSONArray()).objects())local.resolve(owner,result)}},{r->for(result in (r.optJSONArray("results")?:JSONArray()).objects())local.resolve(owner,result);notice("Sync complete. "+r.getJSONObject("summary").toString());refresh{queueScreen()}})}};button("Check connection"){work({api.call("/health")},{queueScreen()})};if(actions.length()==0)card("All caught up","Offline scores and roster actions will be kept here until the server resolves them.");for(a in actions.objects()){val result=a.optJSONObject("result");val p=a.optJSONObject("payload");card(a.optString("type").replace('_',' ').replaceFirstChar{it.uppercase()},"${a.optString("local_status").uppercase()} • ${a.optString("queued_at")}\n${p?.optString("match_id")?:""}${p?.optString("player_id")?:""}"+(if(result!=null)"\n${result.optString("resolution").replace('_',' ')} • Server version ${result.optInt("server_version")} • Processed #${result.optInt("processed_order")}\n"+(if(result.isNull("error_code"))"Resolved by server"else"Rejected: "+result.optString("error_code").replace('_',' ').lowercase())else"\nWaiting to sync"))}}
